insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('NZ:truck-driver','2026-08-11',null,41.11,85500,0,0,0,0,15,8,0,3,1,27,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 733111 Truck Driver (General), aligned to heavy-truck driving that requires the appropriate NZ heavy-vehicle licence class.','shortage_note','Truck Driver (General) is not on the current Green List; earlier transport-sector residence settings are not treated as current shortage evidence; 0/20.','visa_basis','No current Green List residence pathway is assigned to the canonical truck-driver profile; conservative generic-role credit 3/10.','salary_method','Midpoint of Tahatū current most-common Heavy Truck Driver annual pay range NZD 69,000-102,000; 8/10.','entry_basis','Tahatū describes 0-1 year of training and a direct licence-led pathway; 15/15.','entry_burden_basis','A full Class 2, 3, 4 or 5 licence is legally required to drive the corresponding heavy vehicle independently; 1/5.'),'2026-08-11'),
('NZ:logistics-coordinator','2026-08-11',null,36.78,76500,0,0,0,0,12,6,0,3,5,26,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Tahatū Logistics Specialist directly includes Logistics Coordinator. ANZSCO 133611 Supply and Distribution Manager is manager-level and is not forced onto this coordinator profile.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned; 0/20.','visa_basis','A specific coordinator role requires duty-based classification, so generic visa credit is conservative at 3/10.','salary_method','Midpoint of Tahatū current most-common Logistics Specialist annual pay range NZD 62,000-91,000; 6/10.','entry_basis','Tahatū describes 0-2 years of training, while employers commonly value logistics, supply-chain or business study and relevant operations experience; 12/15.','entry_burden_basis','No universal statutory occupational registration applies to Logistics Coordinators; 5/5.'),'2026-08-11'),
('NZ:aircraft-maintenance-technician','2026-08-11',null,54.57,113500,20,0,0,0,6,10,0,10,1,47,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 3231 roll-up of 323111 Aircraft Maintenance Engineer (Avionics), 323112 Aircraft Maintenance Engineer (Mechanical), and 323113 Aircraft Maintenance Engineer (Structures).','shortage_note','All three aircraft-maintenance occupations in this roll-up are on the current Green List Tier 1; 20/20.','visa_basis','Tier 1 can support Straight to Residence when the applicant holds the required CAA New Zealand Aircraft Maintenance Engineer Licence and meets other current requirements; 10/10.','salary_method','Midpoint of Tahatū current most-common Aircraft Maintenance Engineer annual pay range NZD 83,000-144,000; 10/10.','entry_basis','Although Tahatū shows a short training range, the CAA Part 66 licence requires examinations and substantial practical aviation-engineering experience, so accessibility is conservatively scored 6/15.','entry_burden_basis','The Green List scope requires a Civil Aviation Authority of New Zealand AME licence; 1/5.'),'2026-08-11'),
('NZ:commercial-pilot','2026-08-11',null,81.25,169000,0,0,0,0,6,10,0,5,1,22,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 231111 Aeroplane Pilot — commercial fixed-wing scope. Helicopter Pilot 231114 is a separate occupation and is excluded.','shortage_note','Aeroplane Pilot 231111 is not on the current Green List; no occupation-specific shortage credit is assigned; 0/20.','visa_basis','Standard skilled-work treatment may apply when the role and applicant meet current requirements; no targeted Green List residence credit; 5/10.','salary_method','Midpoint of Tahatū current most-common Pilot annual pay range NZD 92,000-246,000; 10/10.','entry_basis','Commercial flying requires progressive flight training, prescribed flight experience, examinations and a commercial pilot licence; 6/15.','entry_burden_basis','CAA commercial pilot licensing, a current Class 1 medical certificate and applicable ratings/currency are mandatory; 1/5.'),'2026-08-11'),
('NZ:marine-engineer','2026-08-11',null,52.88,110000,0,0,0,0,10,10,0,5,1,26,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 231212 Ship''s Engineer, alternative title Marine Engineer.','shortage_note','Ship''s Engineer 231212 is not on the current Green List; regulation is not converted into shortage credit; 0/20.','visa_basis','Standard skilled-work treatment may apply when the position and seafarer meet current requirements; 5/10.','salary_method','Midpoint of Tahatū current most-common Marine Engineer annual pay range NZD 72,000-148,000; 10/10.','entry_basis','Tahatū describes 0-2 years of training, but Maritime NZ certification also requires role-appropriate sea service, training and competency evidence; 10/15.','entry_burden_basis','Covered seagoing engineering duties require the appropriate Maritime New Zealand certificate of competency and endorsements; 1/5.'),'2026-08-11'),
('NZ:deck-officer','2026-08-11',null,43.03,89500,0,0,0,0,8,8,0,5,1,22,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 231214 Ship''s Officer, alternative title Deck Officer.','shortage_note','Ship''s Officer 231214 is not on the current Green List; no occupation-specific shortage credit is assigned; 0/20.','visa_basis','Standard skilled-work treatment may apply when the position and seafarer meet current requirements; 5/10.','salary_method','No clean exact Tahatū Deck Officer pay page was found in the reviewed layer. Midpoint of Tahatū Deckhand annual pay range NZD 64,000-115,000 is used only as a transparent conservative maritime feeder proxy; 8/10.','entry_basis','Officer/watchkeeping progression requires maritime training, sea service and competency certification beyond entry-level deckhand work; 8/15.','entry_burden_basis','Covered deck-officer duties require the appropriate Maritime New Zealand certificate of competency and endorsements; 1/5.'),'2026-08-11'),
('NZ:warehouse-manager','2026-08-11',null,44.23,92000,0,0,0,0,12,8,0,5,5,30,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 133611 Supply and Distribution Manager — manager-level warehouse/distribution scope. This code is not reused for Logistics Coordinator.','shortage_note','Supply and Distribution Manager 133611 is not on the current Green List; 0/20.','visa_basis','Standard skilled-work treatment when genuine manager-level duties and other current requirements are met; 5/10.','salary_method','Midpoint of Tahatū current most-common Transportation, Storage and Distribution Manager annual pay range NZD 69,000-115,000; 8/10.','entry_basis','Tahatū describes 0-2 years of training with operations experience and logistics/business study commonly supporting progression to management; 12/15.','entry_burden_basis','No universal statutory occupational registration applies to Warehouse Managers; 5/5.'),'2026-08-11'),
('NZ:automotive-service-technician','2026-08-11',null,34.50,71760,15,0,0,0,12,4,0,8,5,44,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Canonical profile is constrained to ANZSCO 321211 Motor Mechanic (General), with general/light automotive service emphasis. Diesel Motor Mechanic 321212 and Motorcycle Mechanic 321213 are separate and excluded.','shortage_note','Motor Mechanic (General) 321211 is on the current Green List Tier 2; 15/20.','visa_basis','Tier 2 can support Work to Residence after the qualifying period when the listed Level 4 automotive qualification or applicable NZTA vehicle-inspector appointment and other current requirements are met; 8/10.','salary_method','Midpoint of Tahatū current most-common Automotive Technician hourly pay range NZD 28-41, annualised at 2,080 hours; 4/10.','entry_basis','Tahatū describes 0-4 years of training and the Green List specifies Level 4 automotive qualification pathways or applicable vehicle-inspector appointment; 12/15.','entry_burden_basis','Generic motor-mechanic work is not a universally statutorily registered profession; vehicle-inspector appointment is a specific pathway rather than a universal mechanic register; 5/5.'),'2026-08-11')
